snippet:
# customer support agent: reads the knowledge base and opens tickets, nothing more
agent: support-bot
model: internal-llm-v3
system_prompt_file: prompts/support.txt
tools:
  - {name: search_kb,     access: "read:knowledge-base"}
  - {name: create_ticket, access: "write:tickets"}
  - {name: run_shell,     access: "exec:/bin/bash"}
  - {name: crm_db,        access: "read-write:all_tables"}
human_approval: required_for_write
max_tool_calls: 10
log_tool_calls: true
